module.exports = "<div class=\"row\">\r\n    <div class=\"col s12 m6 l4\">\r\n        <d3s-loading [isLoading]=\"isLoading\"></d3s-loading>\r\n        <div *ngIf=\"!isLoading\" class=\"tile tile-detail\">\r\n            <header>History<d3s-tile-actions [hasAdd]=\"true\" (addClick)=\"formMode=FormMode.Adding;\" [hasFilterMode]=\"true\" [(filterMode)]=\"showSimpleFilter\"></d3s-tile-actions></header>\r\n            <input [hidden]=\"!showSimpleFilter\" #gb type=\"text\" pInputText size=\"100\" placeholder=\"Search...\" style=\"margin-bottom:10px;width:100%;\">                                              \r\n            <p-dataTable [globalFilter]=\"gb\" [value]=\"loads\" selectionMode=\"single\" (onRowSelect)=\"selectedRow=$event.data;\" [rows]=\"20\" [paginator]=\"true\">\r\n                <p-column field=\"Action\" header=\"Action\" sortable=\"true\" [style]=\"{ 'width': '30%' }\" [filter]=\"!showSimpleFilter\"></p-column>\r\n                <p-column field=\"ObjectName\" header=\"Target\" sortable=\"true\" [style]=\"{ 'width': '40%' }\" [filter]=\"!showSimpleFilter\"></p-column>\r\n                <p-column field=\"DateCompleted\" header=\"Date Completed\" sortable=\"true\" [style]=\"{ 'width': '30%' }\" [filter]=\"!showSimpleFilter\">\r\n                    <template let-item=\"rowData\" pTemplate type=\"body\">\r\n                        {{item.DateCompleted | date:'short'}}\r\n                    </template>\r\n                </p-column>\r\n            </p-dataTable>\r\n        </div>\r\n    </div>\r\n    <div class=\"col s12 m6 l8\" [ngSwitch]=\"formMode\">\r\n        <div *ngSwitchCase=\"FormMode.Adding\">\r\n            <div class=\"tile tile-detail\">\r\n                <d3s-load-form (onCancel)=\"formMode = FormMode.Default;\" (onSuccess)=\"formMode = FormMode.Default; load();\"></d3s-load-form>\r\n            </div>\r\n        </div>\r\n        <div *ngSwitchDefault>\r\n            <div class=\"tile tile-detail\">\r\n                <object-detail [objectType]=\"'Load'\" [objectID]=\"selectedRow?.ID\"></object-detail>\r\n            </div>\r\n            <div class=\"tile tile-detail\">\r\n                <d3s-load-item-tile [id]=\"selectedRow?.ID\"></d3s-load-item-tile>\r\n            </div>\r\n        </div>\r\n    </div>\r\n</div>\r\n"

